Here's a complete, self-contained checkout page component. It includes a cart summary, a controlled delivery address form with basic validation, a Pay button, and a back-to-cart action — all via props so it can be wired into any router/state setup.

**CheckoutPage.tsx**
```tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";

export interface CartItem {
  id: string;
  name: string;
  imageUrl?: string;
  unitPrice: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

export interface CheckoutPageProps {
  items: CartItem[];
  currency?: string;
  initialAddress?: Partial<DeliveryAddress>;
  isSubmitting?: boolean;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency,
  }).format(amount);
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required.";
  }
  if (!address.street.trim()) {
    errors.street = "Street address is required.";
  }
  if (!address.city.trim()) {
    errors.city = "City is required.";
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  }
  if (!address.country.trim()) {
    errors.country = "Country is required.";
  }
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[0-9+()\-\s]{6,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  items,
  currency = "USD",
  initialAddress,
  isSubmitting = false,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const shipping = useMemo(() => (items.length > 0 ? 5.99 : 0), [items.length]);
  const total = subtotal + shipping;

  const handleChange = (field: keyof DeliveryAddress) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const value = event.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length === 0 && items.length > 0) {
      onPay(address);
    }
  };

  const isEmptyCart = items.length === 0;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-labelledby="cart-summary-heading">
          <h2 id="cart-summary-heading">Your items</h2>

          {isEmptyCart ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-quantity">Qty: {item.quantity}</span>
                  </div>
                  <div className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity, currency)}
                  </div>
                </li>
              ))}
            </ul>
          )}

          <div className="cart-totals">
            <div className="cart-totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currency)}</span>
            </div>
            <div className="cart-totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping, currency)}</span>
            </div>
            <div className="cart-totals-row cart-totals-total">
              <span>Total</span>
              <span>{formatPrice(total, currency)}</span>
            </div>
          </div>
        </section>

        <section className="address-form-section" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange("fullName")}
                onBlur={handleBlur("fullName")}
                autoComplete="name"
              />
              {touched.fullName && errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleChange("street")}
                onBlur={handleBlur("street")}
                autoComplete="street-address"
              />
              {touched.street && errors.street && (
                <span className="field-error">{errors.street}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange("city")}
                  onBlur={handleBlur("city")}
                  autoComplete="address-level2"
                />
                {touched.city && errors.city && (
                  <span className="field-error">{errors.city}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  onBlur={handleBlur("postalCode")}
                  autoComplete="postal-code"
                />
                {touched.postalCode && errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange("country")}
                onBlur={handleBlur("country")}
                autoComplete="country-name"
              />
              {touched.country && errors.country && (
                <span className="field-error">{errors.country}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange("phone")}
                onBlur={handleBlur("phone")}
                autoComplete="tel"
              />
              {touched.phone && errors.phone && (
                <span className="field-error">{errors.phone}</span>
              )}
            </div>

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isSubmitting || isEmptyCart}
              >
                {isSubmitting ? "Processing..." : `Pay ${formatPrice(total, currency)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

